    "lacunas": [
      "O crédito da extensão depende do término novo, que não pode ser determinado sem as precedências da ficha d_a70f."
    ],
    "motivo": "O aviso autoriza recalcular a extensão e creditar dias não usados, mas o custo resultante depende do término novo desconhecido.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
